 * Runs an instant-runoff count over a parsed election and returns the
 * round-by-round results.
 *
 * Returns:
 *   {
 *     rounds: [
 *       {
 *         counts: [{ name, votes }...],   // continuing candidates, sorted
 *         exhausted: number,
 *         eliminated: name | null,
 *       }, ...
 *     ],
 *     winner: name | null,
 *   }
 */
export function runElection({ candidates, ballots }) {
  let continuing = new Set(candidates)
  const history = Object.create(null)
  for (const name of candidates) history[name] = []

  const rounds = []
  let winner = null

  for (;;) {
    const votes = Object.create(null)
    for (const name of continuing) votes[name] = 0
    let exhausted = 0

    for (const ballot of ballots) {
      const pick = ballot.names.find((name) => continuing.has(name))
      if (pick === undefined) {
        exhausted += ballot.count
      } else {
        votes[pick] += ballot.count
      }
    }

    const activeTotal = ballots.reduce(
      (sum, b) => sum + (b.names.some((n) => continuing.has(n)) ? b.count : 0),
      0,
    )

    for (const name of continuing) history[name].push(votes[name])

    const counts = [...continuing]
      .map((name) => ({ name, votes: votes[name] }))
      .sort((a, b) => (b.votes - a.votes) || (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))

    const roundNo = rounds.length + 1

    if (activeTotal === 0) {
      rounds.push({ counts, exhausted, eliminated: null })
      winner = null
      break
    }

    const majorityWinner = counts.find((c) => c.votes * 2 > activeTotal)
    if (majorityWinner) {
      rounds.push({ counts, exhausted, eliminated: null })
      winner = majorityWinner.name
      break
    }

    const eliminated = pickToEliminate(counts, history, roundNo)
    rounds.push({ counts, exhausted, eliminated })
    continuing = new Set([...continuing].filter((name) => name !== eliminated))
  }

  return { rounds, winner }
}

function pickToEliminate(counts, history, roundNo) {
  const minVotes = Math.min(...counts.map((c) => c.votes))
  let tied = counts.filter((c) => c.votes === minVotes).map((c) => c.name)

  for (;;) {
    if (tied.length === 1) break
    let differentiated = false
    for (let r = 1; r <= roundNo; r++) {
      const vals = tied.map((name) => history[name][r - 1])
      const minV = Math.min(...vals)
      if (!vals.every((v) => v === minV)) {
        tied = tied.filter((name) => history[name][r - 1] === minV)
        differentiated = true
        break
      }
    }
    if (!differentiated) break
  }

  if (tied.length === 1) return tied[0]

  tied.sort((a, b) => (a < b ? 1 : a > b ? -1 : 0))
  return tied[0]
}
"}

